import posixpath
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_note(name: str) -> str:
    """Return the text of the file `name` inside the `notes` directory.

    `name` is untrusted and is resolved relative to `notes` (relative to the
    working directory); subdirectories are allowed (e.g. "sub/b.txt").
    Any name that would resolve outside `notes` (absolute paths, "..",
    symlinks pointing out, NUL bytes, etc.) yields "". A missing,
    unreadable, or non-file target also yields "".
    """
    try:
        if not name or "\x00" in name or "\\" in name:
            return ""
        norm = posixpath.normpath(name)
        if norm == ".." or norm.startswith("../"):
            return ""
        root = Path(NOTES_DIR).resolve()
        rel = Path(name)
        if rel.is_absolute():
            return ""
        target = (root / rel).resolve()
        if not target.is_relative_to(root):
            return ""
        if not target.is_file():
            return ""
        return target.read_text()
    except (OSError, ValueError, UnicodeError, RuntimeError):
        return ""


@pytest.fixture
def notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    d = tmp_path / NOTES_DIR
    d.mkdir()
    (d / "a.txt").write_text("hello")
    (d / "sub").mkdir()
    (d / "sub" / "b.txt").write_text("nested")
    (tmp_path / "secret.txt").write_text("secret")
    return d


def test_reads_top_level_file(notes: Path) -> None:
    assert read_note("a.txt") == "hello"


def test_reads_subdirectory_file(notes: Path) -> None:
    assert read_note("sub/b.txt") == "nested"


def test_inner_dotdot_staying_inside(notes: Path) -> None:
    assert read_note("sub/../a.txt") == "hello"


def test_dot_prefix(notes: Path) -> None:
    assert read_note("./a.txt") == "hello"


def test_missing_file(notes: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name(notes: Path) -> None:
    assert read_note("") == ""


def test_directory_is_not_a_file(notes: Path) -> None:
    assert read_note("sub") == ""
    assert read_note(".") == ""


def test_parent_traversal(notes: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("sub/../../secret.txt") == ""
    assert read_note("../notes/a.txt") == ""


def test_deep_traversal(notes: Path) -> None:
    assert read_note("../../../../../../../../etc/passwd") == ""


def test_absolute_path(notes: Path, tmp_path: Path) -> None:
    assert read_note(str(tmp_path / "secret.txt")) == ""
    assert read_note(str(notes / "a.txt")) == ""
    assert read_note("/etc/passwd") == ""


def test_backslash_traversal(notes: Path) -> None:
    assert read_note("..\\secret.txt") == ""


def test_nul_byte(notes: Path) -> None:
    assert read_note("a.txt\x00../secret.txt") == ""
    assert read_note("a.txt\x00") == ""


def test_symlink_escape_file(notes: Path, tmp_path: Path) -> None:
    (notes / "link.txt").symlink_to(tmp_path / "secret.txt")
    assert read_note("link.txt") == ""


def test_symlink_escape_dir(notes: Path, tmp_path: Path) -> None:
    outside = tmp_path / "outside"
    outside.mkdir()
    (outside / "x.txt").write_text("x")
    (notes / "ld").symlink_to(outside, target_is_directory=True)
    assert read_note("ld/x.txt") == ""


def test_symlink_inside_notes_ok(notes: Path) -> None:
    (notes / "alias.txt").symlink_to(notes / "a.txt")
    assert read_note("alias.txt") == "hello"


def test_sibling_prefix_directory(notes: Path, tmp_path: Path) -> None:
    sibling = tmp_path / "notes2"
    sibling.mkdir()
    (sibling / "x.txt").write_text("x")
    assert read_note("../notes2/x.txt") == ""


def test_unreadable_file(notes: Path) -> None:
    import os

    if os.name == "nt" or os.geteuid() == 0:
        pytest.skip("permissions not enforced")
    p = notes / "locked.txt"
    p.write_text("no")
    p.chmod(0)
    try:
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o600)


def test_invalid_utf8_gives_empty_or_text(notes: Path) -> None:
    (notes / "bin.dat").write_bytes(b"\xff\xfe\x00")
    assert isinstance(read_note("bin.dat"), str)

